// streamSeq is the message's stream sequence, or 0 when metadata is
// unavailable (a synthetic message). All such messages share the zero key,
// which is harmless: they cannot satisfy the breaker's above-the-floor
// condition anyway.
func streamSeq(msg jetstream.Msg) uint64 {
	if meta, err := msg.Metadata(); err == nil && meta != nil {
		return meta.Sequence.Stream
	}
	return 0
}

// capture republishes the raw message and headers to the DLQ subject, tagging
// the reason with its cause.
func (r *Retry) capture(ctx context.Context, msg jetstream.Msg, cause Cause, reason string) error {
	if err := natsmsg.DeadLetter(ctx, r.cfg.Publisher, r.cfg.DLQSubject, msg, string(cause)+": "+reason); err != nil {
		logger, name := r.log()
		logger.ErrorContext(ctx, name+": settle:dlq_publish_failed",
			slog.Any("error", err),
			slog.String("dlq_subject", r.cfg.DLQSubject),
			slog.String("cause", string(cause)))
		return fmt.Errorf("settle:dlq_publish_failed: %w", err)
	}
	return nil
}

// awaitRedelivery leaves the delivery UNTOUCHED so the server's ladder brings
// it back, and completes s.
//
// Not acking is the disposition here, and it is deliberate rather than an
// omission. A consumer's BackOff ladder governs acknowledgement TIMEOUTS: let
// AckWait expire and the server redelivers on the configured rung. A plain
// Nak does the opposite — it asks for immediate redelivery and the ladder is
// never consulted, so a transient failure hot-loops through MaxDeliver and
// reaches the DLQ in milliseconds. Measured against a live server with a
// 3s/3s/3s ladder: Nak() redelivers in 0s, no-ack in 3s.
//
// NakWithDelay does not rescue it either, and the reason is stronger than
// "the client would have to know the delay". The server does not honour the
// requested delay as given: processNak backdates the pending timestamp by
// AckWait, and checkPending then measures it against the CURRENT rung, so the
// effective wait is d + (BackOff[rung] - BackOff[0]). Measured on a
// [200ms, 1200ms] ladder, NakWithDelay(50ms) redelivered at 50ms, then
// 1050ms, then 1050ms. On a growing ladder a client simply cannot express its
// own envelope — which is also the likeliest explanation for ENT-1535's
// unverified "~78s apart against a 5m first rung" observation.
//
// So doing nothing is not merely the tidiest way to defer to the one ladder;
// it is the only disposition whose timing is predictable.
//
// The cost is that the delivery stays ack-pending for the whole rung, so a
// consumer with a long ladder and many concurrent failures needs MaxAckPending
// sized for it. That is inherent to a server-side ladder, not to this choice.
func (r *Retry) awaitRedelivery(ctx context.Context, msg jetstream.Msg, s Settlement) Settlement {
	s.Outcome = OutcomeRetried
	r.observe(ctx, msg, s)
	return s
}

func (r *Retry) observe(ctx context.Context, msg jetstream.Msg, s Settlement) {
	if r.cfg.OnSettle != nil {
		r.cfg.OnSettle(ctx, msg, s)
	}
}

